select
    DATE(order_time) day ,SUM(amount) AS turnover
from orders WHERE order_time >= CURDATE() - INTERVAL 6 DAY AND orders.order_time < CURDATE() + INTERVAL 1 DAY GROUP BY DATE(order_time)

SELECT
        (SELECT COUNT(*) FROM dish    WHERE status = 1) AS dishes,
        (SELECT COUNT(*) FROM setmeal WHERE status = 1) AS setmeals;

SELECT
DATE(o.order_time) AS day,
SUM(o.amount) AS amount,
SUM(o.status IN (2, 3, 4, 5)) AS valid,
SUM(o.status NOT IN (6, 7)) AS total
FROM orders o
WHERE o.order_time >= #{beginTime}
AND o.order_time <  #{endTime}
GROUP BY DATE(o.order_time);

select
    o.number, o.status, o.user_name as consignee, o.phone, o.address,
    o.amount, o.order_time, o.remark,
    od.dish_id, od.number as quantity, od.name as orderDishes
from orders o
left join order_detail od on od.order_id = o.id


        AND o.number = #{number}


        AND o.phone = #{phone}


        AND o.order_time >= #{beginTime}


        AND o.order_time <= #{endTime}


        AND o.status = #{status}

